import { lazy } from "react";
import { Row } from "@/shared/ui/layout/Row";

// Lazy-loaded screens (#perf): only the Console is needed at boot. Each other screen's chunk
// loads on first navigation, keeping the heavy module graph (esp. the planner) off the cold
// startup path — both the dev transform and the production bundle. Shared by the shell's screen
// switcher and the detached-window renderer.
// Settings renders from the HAND-CODED pages. It was migrated to the graph in #3658, rolled back by
// preference in #3758, and the dormant graph path was DELETED in #4183 — a copy nobody renders only
// rots. If Settings returns to the graph, regenerate it from the files of that day.
export const SettingsWorkspace    = lazy(() => import("@/features/settings").then((m) => ({ default: m.SettingsWorkspace })));
// Skills renders FROM THE GRAPH (#3654, epic #3604) — the graph host mounts the authored `skillspage` node;
// the symbol name stays so App.tsx + DetachedWindow (which passes `pageOverride`) need no change.
export const SkillsWorkspace      = lazy(() => import("@/features/skills").then((m) => ({ default: m.SkillsGraphHost })));
// Security renders FROM THE GRAPH (#3646, epic #3604) — the graph host mounts the authored `securitypage`
// node; the symbol name stays so App.tsx + DetachedWindow (which passes `pageOverride`) need no change.
export const LogsWorkspace        = lazy(() => import("@/features/logs").then((m) => ({ default: m.LogsGraphHost })));
// Glance renders FROM THE GRAPH (#4185, epic #3604) — the graph host mounts the authored `glancepage`
// node; the symbol name stays so App.tsx needs no change.
export const GlanceWorkspace      = lazy(() => import("@/features/glance").then((m) => ({ default: m.GlanceGraphHost })));
// THE FIVE GRAPHS (`five-graphs-become-rail-workspaces`) — Components, Teams, Algorithms, Data and
// Sounds are rail Workspaces again. They spent a while folded into the Planner as tabs (#move-to-planner,
// #2785, #2199, #3072); that collapse is reversed, so each is lazy-mounted here like every other screen.
//
// Components and Algorithms are the two heaviest chunks in the app after the planner — the component
// preview/build chain and the knowledge graph respectively — which is exactly why they stay LAZY:
// a rail destination nobody has opened should not be on the cold-start path.
export const ComponentsWorkspace  = lazy(() => import("@/features/designs").then((m) => ({ default: m.DesignsWorkbench })));
export const AlgorithmsWorkspace  = lazy(() => import("@/features/algorithms").then((m) => ({ default: m.AlgorithmsGraphHost })));
export const TeamsWorkspace       = lazy(() => import("@/features/teams").then((m) => ({ default: m.TeamsGraphHost })));
export const DataWorkspace        = lazy(() => import("@/features/data").then((m) => ({ default: m.DataGraphHost })));
export const SoundsWorkspace      = lazy(() => import("@/features/sounds").then((m) => ({ default: m.SoundsGraphHost })));
// The session-memory store's window (`a-memory-workspace-shows-what-we-know`). Lazy for the same
// reason as the two below: it reads `bsc memory` on mount, and a screen nobody has opened should not
// be on the cold-start path.
export const MemoryWorkspace      = lazy(() => import("@/features/memory").then((m) => ({ default: m.MemoryWorkspace })));
// The credential store's window. Lazy like every other non-Console destination: it reads `bsc secret`
// on mount, and a screen nobody has opened should not be on the cold-start path.
export const CredentialsWorkspace = lazy(() => import("@/features/credentials").then((m) => ({ default: m.CredentialsWorkspace })));

/** Lightweight placeholder shown while a lazy screen's chunk loads. */
export function WorkspaceFallback() {
  return (
    <Row className="mono" justify="center" style={{ flex: 1, color: "var(--fg-dim)", fontSize: 12 }}>
      loading…
    </Row>
  );
}
